contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _unlockTime, uint _depositAmount, uint _collectAmount) public payable {
        require(_depositAmount > 0 && _collectAmount >= _depositAmount);
        require(address(this).balance >= _depositAmount);
        c.Put{value: _depositAmount}(_unlockTime);
        // Ensure unlock time has passed for our test
        // We skip time manipulation; the Put uses max(_unlockTime, block.timestamp) so unlockTime >= block.timestamp.
        // Since we cannot force time forward, we rely on the fact that unlockTime is set to block.timestamp if _unlockTime <= block.timestamp.
        // To guarantee block.timestamp > acc.unlockTime, we would need time travel, which is not allowed.
        // Instead, we exploit the condition: if _unlockTime > block.timestamp, unlockTime is > block.timestamp, so Collect reverts regardless of balance.
        // The rule must hold for all inputs, so we state it under the precondition that Collect would otherwise proceed.
        // We just call Collect and assert based on revert.
        bool reverted;
        try c.Collect(_collectAmount) { reverted = false; } catch { reverted = true; }
        // If no revert, then _collectAmount must have been < acc.balance? No, in original P, condition is >= _am. So collect succeeds when acc.balance >= _am, acc.balance >= MinSum, and time > unlockTime.
        // We cannot observe acc.balance directly (public mapping getter exists: Acc(address) returns Holder). Holder is struct with unlockTime and balance.
        // Actually Acc is public, so we can call c.Acc(address) and get unlockTime and balance.
        // We'll do that if needed.
        // The rule: if collect reverts, it must be that the account balance is less than the requested amount, or the balance is less than MinSum, or time <= unlockTime.
        // For the counterexample, they used a case where balance >= MinSum, time > unlockTime, and _am <= balance, but mutant reverts because it uses <.
        // So the rule is: !reverted || (balance < _am || balance < MinSum || block.timestamp <= unlockTime).
        // We can read balance and unlockTime via c.Acc(address(this)).
        (uint unlockTime, uint balance) = c.Acc(address(this));
        assert(!reverted || (balance < _collectAmount || balance < c.MinSum() || block.timestamp <= unlockTime));
    }
    receive() external payable {}
}

