pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address actor, uint256 depositVal, uint256 withdrawAmt, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        vm.assume(depositVal >= 1 ether);
        vm.assume(depositVal <= 10000 ether);
        vm.assume(withdrawAmt <= 10000 ether);
        vm.assume(unlockTime > block.timestamp);

        // deposit funds and set unlockTime
        vm.deal(actor, depositVal);
        vm.prank(actor);
        c.Put{value: depositVal}(unlockTime);

        // forward time past unlock
        vm.warp(unlockTime + 1);

        uint256 contractBalBefore = address(c).balance;

        // does the actor have enough balance? record before call
        ( , uint256 accBalance) = c.Acc(actor);
        bool hasEnough = accBalance >= withdrawAmt;

        bool ok;
        vm.prank(actor);
        try c.Collect(withdrawAmt) { ok = true; } catch { ok = false; }

        uint256 contractBalAfter = address(c).balance;

        // INVARIANT: if the actor did NOT have enough balance, the contract's ETH balance MUST NOT decrease
        if (!hasEnough) {
            assertTrue(contractBalAfter >= contractBalBefore);
        } else {
            // case with enough balance: always succeeds in reference, so ETH balance can decrease, but invariant holds trivially
            assertTrue(true);
        }
    }
}

