pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        // Ensure initial actor balance is exactly amount and >= MinSum
        vm.assume(amount >= c.MinSum());
        // Ensure unlockTime is in the past so Collect can proceed
        vm.warp(block.timestamp + 1);
        uint256 pastTime = block.timestamp - 1;
        // Fund actor and deposit
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(pastTime);
        // Ensure the contract has at least the amount to collect
        vm.assume(address(c).balance >= amount);
        // Record balance before collect
        uint256 balBefore = actor.balance;
        // Attempt to Collect the full deposited amount
        vm.prank(actor);
        // We catch revert to check success; the rule is about whether it should succeed
        try c.Collect(amount) returns (bool) {
            // If it succeeded, the actor balance must have increased by amount
            assertEq(actor.balance, balBefore + amount);
        } catch {
            // If it failed, the actor balance must be unchanged
            assertEq(actor.balance, balBefore);
        }
    }
}

